## 17.9 代码示例完整实现

### 17.9.1 完整的F^H D计算核函数

```cuda
#include <cuda_runtime.h>
#include <math.h>

#define PI 3.14159265358979323846f
#define FHD_THREADS_PER_BLOCK 256
#define TILE_SIZE 256

// 第一步:计算Mu核函数
__global__ void cmpMu_kernel(float* rPhi, float* iPhi, 
                              float* rD, float* iD,
                              float* rMu, float* iMu, int M) {
    int m = blockIdx.x * blockDim.x + threadIdx.x;

    if (m < M) {
        rMu[m] = rPhi[m] * rD[m] + iPhi[m] * iD[m];
        iMu[m] = rPhi[m] * iD[m] - iPhi[m] * rD[m];
    }
}

// 第二步:计算F^H D核函数(优化版本)
__global__ void cmpFhD_kernel_optimized(float* kx, float* ky, float* kz,
                                         float* x, float* y, float* z,
                                         float* rMu, float* iMu,
                                         float* rFhD, float* iFhD,
                                         int M, int N) {
    int n = blockIdx.x * blockDim.x + threadIdx.x;

    if (n < N) {
        // 寄存器变量:减少全局内存访问
        float x_reg = x[n];
        float y_reg = y[n];
        float z_reg = z[n];
        float rFhD_reg = 0.0f;
        float iFhD_reg = 0.0f;

        // 遍历所有k空间样本
        for (int m = 0; m < M; m++) {
            // 计算指数项
            float expFhD = 2.0f * PI * (kx[m] * x_reg + 
                                        ky[m] * y_reg + 
                                        kz[m] * z_reg);

            // 计算三角函数(使用快速版本)
            float cArg, sArg;
            sincosf(expFhD, &sArg, &cArg);

            // 累加贡献
            rFhD_reg += rMu[m] * cArg - iMu[m] * sArg;
            iFhD_reg += iMu[m] * cArg + rMu[m] * sArg;
        }

        // 写回全局内存
        rFhD[n] = rFhD_reg;
        iFhD[n] = iFhD_reg;
    }
}

// 使用共享内存的优化版本
__global__ void cmpFhD_kernel_shared(float* kx, float* ky, float* kz,
                                      float* rMu, float* iMu,
                                      float* x, float* y, float* z,
                                      float* rFhD, float* iFhD,
                                      int M, int N) {
    int n = blockIdx.x * blockDim.x + threadIdx.x;

    // 共享内存声明
    __shared__ float kx_tile[TILE_SIZE];
    __shared__ float ky_tile[TILE_SIZE];
    __shared__ float kz_tile[TILE_SIZE];
    __shared__ float rMu_tile[TILE_SIZE];
    __shared__ float iMu_tile[TILE_SIZE];

    if (n < N) {
        // 寄存器变量
        float x_reg = x[n];
        float y_reg = y[n];
        float z_reg = z[n];
        float rFhD_reg = 0.0f;
        float iFhD_reg = 0.0f;

        // 分块处理k空间数据
        for (int tile_start = 0; tile_start < M; tile_start += TILE_SIZE) {
            // 协作加载到共享内存
            int load_idx = tile_start + threadIdx.x;
            if (load_idx < M) {
                kx_tile[threadIdx.x] = kx[load_idx];
                ky_tile[threadIdx.x] = ky[load_idx];
                kz_tile[threadIdx.x] = kz[load_idx];
                rMu_tile[threadIdx.x] = rMu[load_idx];
                iMu_tile[threadIdx.x] = iMu[load_idx];
            }
            __syncthreads();

            // 使用共享内存数据计算
            int tile_end = min(TILE_SIZE, M - tile_start);
            for (int m = 0; m < tile_end; m++) {
                float expFhD = 2.0f * PI * (kx_tile[m] * x_reg + 
                                            ky_tile[m] * y_reg + 
                                            kz_tile[m] * z_reg);

                float cArg, sArg;
                sincosf(expFhD, &sArg, &cArg);

                rFhD_reg += rMu_tile[m] * cArg - iMu_tile[m] * sArg;
                iFhD_reg += iMu_tile[m] * cArg + rMu_tile[m] * sArg;
            }
            __syncthreads();
        }

        // 写回全局内存
        rFhD[n] = rFhD_reg;
        iFhD[n] = iFhD_reg;
    }
}

// 主机端调用函数
extern "C" void computeFhD(float* h_kx, float* h_ky, float* h_kz,
                           float* h_x, float* h_y, float* h_z,
                           float* h_rPhi, float* h_iPhi,
                           float* h_rD, float* h_iD,
                           float* h_rFhD, float* h_iFhD,
                           int M, int N) {
    // 设备内存指针
    float *d_kx, *d_ky, *d_kz;
    float *d_x, *d_y, *d_z;
    float *d_rPhi, *d_iPhi, *d_rD, *d_iD;
    float *d_rMu, *d_iMu;
    float *d_rFhD, *d_iFhD;

    // 分配设备内存
    cudaMalloc(&d_kx, M * sizeof(float));
    cudaMalloc(&d_ky, M * sizeof(float));
    cudaMalloc(&d_kz, M * sizeof(float));
    cudaMalloc(&d_x, N * sizeof(float));
    cudaMalloc(&d_y, N * sizeof(float));
    cudaMalloc(&d_z, N * sizeof(float));
    cudaMalloc(&d_rPhi, M * sizeof(float));
    cudaMalloc(&d_iPhi, M * sizeof(float));
    cudaMalloc(&d_rD, M * sizeof(float));
    cudaMalloc(&d_iD, M * sizeof(float));
    cudaMalloc(&d_rMu, M * sizeof(float));
    cudaMalloc(&d_iMu, M * sizeof(float));
    cudaMalloc(&d_rFhD, N * sizeof(float));
    cudaMalloc(&d_iFhD, N * sizeof(float));

    // 复制输入数据到设备
    cudaMemcpy(d_kx, h_kx, M * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_ky, h_ky, M * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_kz, h_kz, M * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_x, h_x, N * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_y, h_y, N * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_z, h_z, N * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_rPhi, h_rPhi, M * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_iPhi, h_iPhi, M * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_rD, h_rD, M * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(d_iD, h_iD, M * sizeof(float), cudaMemcpyHostToDevice);

    // 初始化输出
    cudaMemset(d_rFhD, 0, N * sizeof(float));
    cudaMemset(d_iFhD, 0, N * sizeof(float));

    // 计算网格和线程块大小
    int blocks_M = (M + FHD_THREADS_PER_BLOCK - 1) / FHD_THREADS_PER_BLOCK;
    int blocks_N = (N + FHD_THREADS_PER_BLOCK - 1) / FHD_THREADS_PER_BLOCK;

    // 第一步:计算Mu
    cmpMu_kernel<<<blocks_M, FHD_THREADS_PER_BLOCK>>>(
        d_rPhi, d_iPhi, d_rD, d_iD, d_rMu, d_iMu, M
    );

    // 第二步:计算F^H D(使用共享内存版本)
    cmpFhD_kernel_shared<<<blocks_N, FHD_THREADS_PER_BLOCK>>>(
        d_kx, d_ky, d_kz, d_rMu, d_iMu,
        d_x, d_y, d_z, d_rFhD, d_iFhD, M, N
    );

    // 复制结果回主机
    cudaMemcpy(h_rFhD, d_rFhD, N * sizeof(float), cudaMemcpyDeviceToHost);
    cudaMemcpy(h_iFhD, d_iFhD, N * sizeof(float), cudaMemcpyDeviceToHost);

    // 释放设备内存
    cudaFree(d_kx);
    cudaFree(d_ky);
    cudaFree(d_kz);
    cudaFree(d_x);
    cudaFree(d_y);
    cudaFree(d_z);
    cudaFree(d_rPhi);
    cudaFree(d_iPhi);
    cudaFree(d_rD);
    cudaFree(d_iD);
    cudaFree(d_rMu);
    cudaFree(d_iMu);
    cudaFree(d_rFhD);
    cudaFree(d_iFhD);
}
